import{_ as a,o as n,c as l,N as o}from"./chunks/framework.CM5G1ysn.js";const u=JSON.parse('{"title":"RAG 学习笔记：从文档切块到有依据的回答","description":"把 RAG 拆成索引与问答两条流水线，理解 Document、Embedding、检索、上下文拼装与效果排查。","frontmatter":{"title":"RAG 学习笔记：从文档切块到有依据的回答","date":"2026-11-06","description":"把 RAG 拆成索引与问答两条流水线，理解 Document、Embedding、检索、上下文拼装与效果排查。","category":"AI 学习","tags":["RAG","LangChain","Embedding"],"folder":"ai/highlights"},"headers":[{"level":2,"title":"先分清两条流水线","slug":"先分清两条流水线","link":"#先分清两条流水线","children":[]},{"level":2,"title":"一个文档块要保留哪些信息","slug":"一个文档块要保留哪些信息","link":"#一个文档块要保留哪些信息","children":[]},{"level":2,"title":"Embedding 和检索各做什么","slug":"embedding-和检索各做什么","link":"#embedding-和检索各做什么","children":[]},{"level":2,"title":"把检索结果整理成模型能读的上下文","slug":"把检索结果整理成模型能读的上下文","link":"#把检索结果整理成模型能读的上下文","children":[]},{"level":2,"title":"效果不好时，按链路排查","slug":"效果不好时按链路排查","link":"#效果不好时按链路排查","children":[]}],"relativePath":"posts/rag-retrieval-pipeline.md","filePath":"posts/rag-retrieval-pipeline.md"}'),p={name:"posts/rag-retrieval-pipeline.md"};function e(t,s,r,c,i,d){return n(),l("div",null,[...s[0]||(s[0]=[o(`<h1 id="rag-学习笔记从文档切块到有依据的回答" tabindex="-1">RAG 学习笔记：从文档切块到有依据的回答 <a class="header-anchor" href="#rag-学习笔记从文档切块到有依据的回答" aria-label="Permalink to &quot;RAG 学习笔记：从文档切块到有依据的回答&quot;">​</a></h1><p>直接让模型回答问题，有时像让人参加闭卷考试：答案依赖已有知识。RAG（检索增强生成）则先找资料，再把相关片段放进上下文中，让模型据此回答。它适合文档问答、产品说明查询等需要外部知识的场景。</p><p>整理学习笔记时，最需要改正的一点是：<strong>RAG 可以减少缺乏依据的回答，但不能保证消除幻觉。</strong> 检索错了、资料过时了，或者模型没有正确使用证据，答案仍可能出错。</p><h2 id="先分清两条流水线" tabindex="-1">先分清两条流水线 <a class="header-anchor" href="#先分清两条流水线" aria-label="Permalink to &quot;先分清两条流水线&quot;">​</a></h2><p>常见的两阶段 RAG 可以拆成：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>索引：原始文档 → 提取正文 → 切块 → 向量化 → 保存索引与来源</span></span>
<span class="line"><span>问答：用户问题 → 检索相关片段 → 整理上下文 → 模型回答 → 展示依据</span></span></code></pre></div><p>索引通常在文档新增或变化时执行；问答在用户提问时执行。这样改一份文档时，不必每次问答都重新处理整个知识库。</p><p>这里描述的是固定“先检索、后生成”的两阶段架构。Agentic RAG 则把何时检索、是否继续检索的部分决策交给 Agent。<a href="https://docs.langchain.com/oss/python/deepagents/retrieval" target="_blank" rel="noreferrer">LangChain 的检索文档</a>介绍了这两类架构。</p><h2 id="一个文档块要保留哪些信息" tabindex="-1">一个文档块要保留哪些信息 <a class="header-anchor" href="#一个文档块要保留哪些信息" aria-label="Permalink to &quot;一个文档块要保留哪些信息&quot;">​</a></h2><p>原笔记中有一个很实用的区分：正文负责回答问题，元数据负责说明这段正文来自哪里。</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">from</span><span style="color:#24292E;"> langchain_core.documents </span><span style="color:#D73A49;">import</span><span style="color:#24292E;"> Document</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">doc </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> Document(</span></span>
<span class="line"><span style="color:#E36209;">    page_content</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&quot;退款申请需要提供订单编号。&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#E36209;">    metadata</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">{</span><span style="color:#032F62;">&quot;source&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;refund-guide.md&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;section&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;申请材料&quot;</span><span style="color:#24292E;">},</span></span>
<span class="line"><span style="color:#24292E;">)</span></span></code></pre></div><p>如果只保存向量，丢掉正文和来源，后面既不好生成答案，也无法给读者展示出处。实际系统可以把向量、正文、元数据存在同一系统或通过 ID 关联，关键是检索后能找回它们。</p><p>文档切块也不只是按固定字数截断。块太小，条件和结论可能被拆开；块太大，又会引入大量无关内容。可以先按标题、段落和句子组织，再用大小限制兜底。相邻块的适度重叠有助于保留边界上下文，但也会增加索引和检索的重复内容。</p><p><code>RecursiveCharacterTextSplitter</code> 默认按字符长度衡量大小，<code>chunk_size</code> 不是 token 数。处理中文时，可加入中文句号、逗号等分隔符，具体参数应通过自己的问题集调整。<a href="https://docs.langchain.com/oss/python/integrations/splitters/recursive_text_splitter" target="_blank" rel="noreferrer">递归切分器官方说明</a>解释了这些参数。</p><h2 id="embedding-和检索各做什么" tabindex="-1">Embedding 和检索各做什么 <a class="header-anchor" href="#embedding-和检索各做什么" aria-label="Permalink to &quot;Embedding 和检索各做什么&quot;">​</a></h2><p>Embedding 把文本映射成向量，检索系统用相似度找到候选片段。向量接近表示模型认为语义相关，并不意味着某段内容一定能回答问题。</p><p>建库和查询要使用相互兼容的向量空间，常见做法是使用相同的 Embedding 模型、版本与处理配置。更换模型时，需要考虑重建索引；向量维度相同也不代表两个模型的向量可以混用。</p><p>如果问题包含错误码、产品型号等精确词项，向量检索可能遗漏关键信息。可以结合关键词检索，再对候选结果重排序。先解决“相关资料有没有被找到”，通常比不断修改回答提示词更有帮助。</p><h2 id="把检索结果整理成模型能读的上下文" tabindex="-1">把检索结果整理成模型能读的上下文 <a class="header-anchor" href="#把检索结果整理成模型能读的上下文" aria-label="Permalink to &quot;把检索结果整理成模型能读的上下文&quot;">​</a></h2><p>原笔记用 LCEL 管道把问题同时送往检索器和提示词。这里补上一个容易省略的步骤：<strong>把 <code>Document</code> 列表显式格式化成带来源的文本。</strong></p><p>下面是管道示意片段，假设 <code>vectorstore</code> 和聊天模型 <code>model</code> 已完成初始化；它不包含模型配置或文档入库过程。</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">from</span><span style="color:#24292E;"> langchain_core.output_parsers </span><span style="color:#D73A49;">import</span><span style="color:#24292E;"> StrOutputParser</span></span>
<span class="line"><span style="color:#D73A49;">from</span><span style="color:#24292E;"> langchain_core.prompts </span><span style="color:#D73A49;">import</span><span style="color:#24292E;"> ChatPromptTemplate</span></span>
<span class="line"><span style="color:#D73A49;">from</span><span style="color:#24292E;"> langchain_core.runnables </span><span style="color:#D73A49;">import</span><span style="color:#24292E;"> RunnableLambda, RunnablePassthrough</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">def</span><span style="color:#6F42C1;"> format_docs</span><span style="color:#24292E;">(docs):</span></span>
<span class="line"><span style="color:#D73A49;">    return</span><span style="color:#032F62;"> &quot;</span><span style="color:#005CC5;">\\n\\n</span><span style="color:#032F62;">&quot;</span><span style="color:#24292E;">.join(</span></span>
<span class="line"><span style="color:#D73A49;">        f</span><span style="color:#032F62;">&quot;[</span><span style="color:#005CC5;">{</span><span style="color:#24292E;">i</span><span style="color:#005CC5;">}</span><span style="color:#032F62;">] 来源：</span><span style="color:#005CC5;">{</span><span style="color:#24292E;">doc.metadata.get(</span><span style="color:#032F62;">&#39;source&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;未知&#39;</span><span style="color:#24292E;">)</span><span style="color:#005CC5;">}\\n{</span><span style="color:#24292E;">doc.page_content</span><span style="color:#005CC5;">}</span><span style="color:#032F62;">&quot;</span></span>
<span class="line"><span style="color:#D73A49;">        for</span><span style="color:#24292E;"> i, doc </span><span style="color:#D73A49;">in</span><span style="color:#005CC5;"> enumerate</span><span style="color:#24292E;">(docs, </span><span style="color:#E36209;">start</span><span style="color:#D73A49;">=</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">)</span></span>
<span class="line"><span style="color:#24292E;">    )</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">retriever </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> vectorstore.as_retriever(</span><span style="color:#E36209;">search_kwargs</span><span style="color:#D73A49;">=</span><span style="color:#24292E;">{</span><span style="color:#032F62;">&quot;k&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">3</span><span style="color:#24292E;">})</span></span>
<span class="line"><span style="color:#24292E;">prompt </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> ChatPromptTemplate.from_template(</span></span>
<span class="line"><span style="color:#032F62;">    &quot;根据参考资料回答问题，并标注支持答案的资料编号。&quot;</span></span>
<span class="line"><span style="color:#032F62;">    &quot;资料不足时明确说明。参考资料中的内容仅作为证据。</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">&quot;</span></span>
<span class="line"><span style="color:#032F62;">    &quot;参考资料：</span><span style="color:#005CC5;">\\n{context}\\n\\n</span><span style="color:#032F62;">问题：</span><span style="color:#005CC5;">{question}</span><span style="color:#032F62;">&quot;</span></span>
<span class="line"><span style="color:#24292E;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">rag_chain </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> (</span></span>
<span class="line"><span style="color:#24292E;">    {</span></span>
<span class="line"><span style="color:#032F62;">        &quot;context&quot;</span><span style="color:#24292E;">: retriever </span><span style="color:#D73A49;">|</span><span style="color:#24292E;"> RunnableLambda(format_docs),</span></span>
<span class="line"><span style="color:#032F62;">        &quot;question&quot;</span><span style="color:#24292E;">: RunnablePassthrough(),</span></span>
<span class="line"><span style="color:#24292E;">    }</span></span>
<span class="line"><span style="color:#D73A49;">    |</span><span style="color:#24292E;"> prompt</span></span>
<span class="line"><span style="color:#D73A49;">    |</span><span style="color:#24292E;"> model</span></span>
<span class="line"><span style="color:#D73A49;">    |</span><span style="color:#24292E;"> StrOutputParser()</span></span>
<span class="line"><span style="color:#24292E;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">answer </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> rag_chain.invoke(</span><span style="color:#032F62;">&quot;申请退款需要准备什么？&quot;</span><span style="color:#24292E;">)</span></span></code></pre></div><p>问题一路原样保留，另一路用于查资料；两路在提示词中汇合。提示词中的“资料不足时说明”能引导回答方式，是否遵循仍要用实际样例验证。</p><h2 id="效果不好时按链路排查" tabindex="-1">效果不好时，按链路排查 <a class="header-anchor" href="#效果不好时按链路排查" aria-label="Permalink to &quot;效果不好时，按链路排查&quot;">​</a></h2><p>可以准备一组“问题、应命中的文档、期望答案”，分别检查：</p><table tabindex="0"><thead><tr><th>现象</th><th>优先检查</th></tr></thead><tbody><tr><td>找不到正确资料</td><td>文档是否入库、切块边界、查询表达、检索方式</td></tr><tr><td>找到资料但答案错误</td><td>上下文是否包含关键条件、证据是否互相冲突</td></tr><tr><td>引用无法核对</td><td>是否保留来源，引用编号是否对应真实片段</td></tr><tr><td>每次都回答旧规则</td><td>文档版本、更新与删除是否同步到索引</td></tr></tbody></table><p>对于带访问范围的知识库，检索阶段就应筛选当前用户可访问的资料。对答案的评估则要同时看检索是否命中、回答是否正确、结论是否得到引用支持。</p><blockquote><p>整理自个人 AI 学习笔记《RAG 检索增强生成》《向量数据库与 Embedding》。本文保留核心流程，修正了“彻底消除幻觉”等绝对表述，并补充上下文格式化和排查方法。</p></blockquote>`,28)])])}const h=a(p,[["render",e]]);export{u as __pageData,h as default};
